package com.aistock.scheduler.task;
import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
@Tag("mysql") class VerificationScanMysqlTest {
 final TaskMysqlTest fixture=new TaskMysqlTest();final TaskRepository tasks=fixture.repo();final Instant NOW=Instant.parse("2026-10-05T13:00:00Z");final LocalDate DUE=LocalDate.parse("2026-10-05");
 final String a="11111111-1111-1111-1111-111111111111",b="22222222-2222-2222-2222-222222222222";
 PredictionTaskClient.Item item(String id){return new PredictionTaskClient.Item(id,"SH600030",DUE,"origin-share-close-v1");}
 VerificationScanRepository repo(){return new VerificationScanRepository(fixture.jdbc,tasks);}
 @Test void pageAndTasksCommitAtomicallyAndStaleScanDoesNotAdvance(){var r=repo();var first=r.cursor(DUE,NOW);var page=new PredictionTaskClient.Page(DUE,List.of(item(a)),a);assertTrue(r.publish(first,page,NOW));assertFalse(r.publish(first,page,NOW));assertEquals(1,tasks.list().size());assertEquals(a,new VerificationScanRepository(fixture.jdbc,tasks).cursor(DUE,NOW).afterId());var second=r.cursor(DUE,NOW);assertTrue(r.publish(second,new PredictionTaskClient.Page(DUE,List.of(item(b)),null),NOW));assertNull(r.cursor(DUE,NOW).afterId());var restart=r.cursor(DUE,NOW);r.publish(restart,page,NOW);assertEquals(2,tasks.list().size());}
 @Test void failedPagePreservesCursorAndChangedCutoffInvalidatesOldPage(){var r=repo();var cursor=r.cursor(DUE,NOW);var newer=r.cursor(DUE.plusDays(1),NOW.plusSeconds(86400));assertNull(newer.afterId());assertFalse(r.publish(cursor,new PredictionTaskClient.Page(DUE,List.of(item(a)),a),NOW.plusSeconds(86400)));assertEquals(DUE.plusDays(1),r.cursor(DUE,NOW).cutoffDate());var client=mock(PredictionTaskClient.class);when(client.due(any(),any())).thenThrow(new IllegalStateException("down"));var plan=new DailyVerificationPlan(r,client,Clock.fixed(NOW.plusSeconds(86400),ZoneOffset.UTC),"t",false);assertFalse(plan.runOnce());assertEquals(newer.revision(),r.cursor(DUE.plusDays(1),NOW.plusSeconds(86400)).revision());assertEquals(0,tasks.list().size());}
 @Test void invalidSecondItemRollsBackBothTasksAndCursor(){var r=repo();var cursor=r.cursor(DUE,NOW);var invalid=new PredictionTaskClient.Item(b,"SH600030",DUE,"unsupported");assertThrows(RuntimeException.class,()->r.publish(cursor,new PredictionTaskClient.Page(DUE,List.of(item(a),invalid),null),NOW));assertEquals(0,tasks.list().size());assertEquals(cursor.revision(),r.cursor(DUE,NOW).revision());}
 @Test void dailyPageUsesBeforeTwentyCutoffAndNoDueCreatesNoTask(){var r=repo();var client=mock(PredictionTaskClient.class);when(client.due(any(),any())).thenAnswer(call->new PredictionTaskClient.Page(call.getArgument(0),List.of(),null));var plan=new DailyVerificationPlan(r,client,Clock.fixed(Instant.parse("2026-10-05T03:00:00Z"),ZoneOffset.UTC),"t",true);assertTrue(plan.runOnce());verify(client).due(DUE.minusDays(1),null);assertEquals(0,tasks.list().size());}
 @Test void concurrentSamePageOnlyAdvancesOnce()throws Exception{var r=repo();var cursor=r.cursor(DUE,NOW);var page=new PredictionTaskClient.Page(DUE,List.of(item(a)),a);var pool=java.util.concurrent.Executors.newFixedThreadPool(2);try{var x=pool.submit(()->r.publish(cursor,page,NOW));var y=pool.submit(()->r.publish(cursor,page,NOW));assertEquals(1,java.util.stream.Stream.of(x.get(),y.get()).filter(Boolean::booleanValue).count());assertEquals(1,tasks.list().size());assertEquals(cursor.revision()+1,r.cursor(DUE,NOW).revision());}finally{pool.shutdownNow();}}
}
